const P=TrufProgress;
let metricVenue='All venues',metricPeriod='all',progressSport='All sports',previewProgress=false;
function metricsPanel(){
 const venues=[...new Set([...state.matches,...state.slots].map(m=>m.venue))];if(!venues.includes(metricVenue))metricVenue='All venues';
 const v=P.metrics(state,metricVenue,metricPeriod);
 return `<section class="panel"><div class="section-head" style="margin-top:0"><h2>Booking metrics</h2><span class="demo">DEMO DATA</span></div><div class="toolbar"><label>Playing area <select aria-label="Metrics venue" onchange="metricVenue=this.value;render()"><option>All venues</option>${venues.map(n=>`<option ${n===metricVenue?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label>Match dates <select aria-label="Metrics period" onchange="metricPeriod=this.value;render()"><option value="all" ${metricPeriod==='all'?'selected':''}>All dates</option><option value="past30" ${metricPeriod==='past30'?'selected':''}>Past 30 days</option><option value="next7" ${metricPeriod==='next7'?'selected':''}>Next 7 days</option></select></label></div>${stats([['Matches created',v.total],['Confirmed / completed',v.confirmed],['Cancelled / expired',v.cancelled]])}${stats([['Recorded demo payments',money(v.gross)],['Demo refunds',money(v.refunds)],['Net demo collections',money(v.net)]])}<p class="note">${v.pending} waiting for players. Filtered by scheduled match date (IST). Collections count recorded demo payments only—not fictional seed players, settlement income, or profit. Venue filters demonstrate reporting; they are not owner access controls.</p><div class="table-wrap"><table><thead><tr><th>Sport</th><th>Matches</th><th>Confirmed / completed</th></tr></thead><tbody>${D.sports.map(s=>{let list=v.matches.filter(m=>m.sport===s);return `<tr><td>${s}</td><td>${list.length}</td><td>${list.filter(m=>m.status==='completed'||m.status==='open'&&m.joined===m.total).length}</td></tr>`}).join('')}</tbody></table></div><button style="margin-top:16px" onclick="go(role+'/payments')">Open payment records ↗</button></section>`;
}
function sampleAttendance(){const week=P.monday(P.day(Date.now()));return [0,1,2].map((n)=>({match:-n-1,date:new Date(week-n*604800000).toISOString().slice(0,10),sport:'Football',title:'Sample football game'}))}
function progressPage(){
 const rows=previewProgress?sampleAttendance():state.attendance||[],p=P.progress(rows,progressSport),overall=P.progress(rows);
 const rewards=[{id:'first-game',name:'First game',description:'Attend your first game',goal:1,value:overall.played.length},{id:'three-weeks',name:'Finding your rhythm',description:'Play in 3 consecutive weeks',goal:3,value:overall.best},{id:'five-games',name:'Regular player',description:'Attend 5 games',goal:5,value:overall.played.length}];
 return title('Your game. Your progress.','A simple record of showing up and playing.')+`<div class="toolbar"><label>Sport <select aria-label="Progress sport" onchange="progressSport=this.value;render()">${['All sports',...D.sports].map(s=>`<option ${s===progressSport?'selected':''}>${s}</option>`).join('')}</select></label><label><input type="checkbox" ${previewProgress?'checked':''} onchange="previewProgress=this.checked;render()"> Preview sample progress</label></div>${previewProgress?'<div class="notice">SAMPLE PREVIEW · These three fictional games are not saved. Reward claims are disabled in this view.</div>':''}${stats([['Games attended',p.played.length],['Current weekly streak',p.streak+' weeks'],['Play points',p.points]])}<div class="two"><section class="panel"><h2>Keep your weekly streak going</h2><p class="muted">Play at least once each Monday–Sunday week. A current streak can continue from last week until this week ends. Dates use IST.</p><div class="week-grid">${p.weeks.map(w=>`<div class="week-box ${w.played?'played':''}" title="Week starting ${w.date}"><span>${w.played?'✓':'—'}</span><small>${dateLabel(w.date)}</small></div>`).join('')}</div><p class="note">Best streak: ${p.best} weeks · ${p.hours} hours recorded (one-hour games). Only owner-marked attendance earns 100 points per game.</p><button onclick="go('discover')">Find your next game ↗</button></section><section class="panel"><h2>Your sport record</h2>${D.sports.map(s=>{const n=P.progress(rows,s).played.length;return `<div class="activity row"><span>${s}</span><strong>${n} ${n===1?'game':'games'}</strong></div>`}).join('')}<p class="note">Paid, cancelled, expired, and unverified bookings do not award play points.</p></section></div><section class="panel"><h2>Rewards to work toward</h2><p class="muted">All-sport achievements. Collectible demo badges only—no cash value or discounts.</p><div class="grid">${rewards.map(r=>{const unlocked=r.value>=r.goal,claimed=(state.claimedRewards||[]).includes(r.id)&&!previewProgress;return `<article class="card"><div class="card-body" style="padding-top:20px"><span class="badge ${unlocked?'':'neutral'}">${claimed?'Collected':unlocked?'Unlocked':'In progress'}</span><h3 style="margin-top:12px">${r.name}</h3><p class="meta">${r.description}</p><div class="progress"><i style="width:${Math.min(100,r.value/r.goal*100)}%"></i></div><p class="meta">${Math.min(r.value,r.goal)} / ${r.goal}</p><button class="small primary" ${!unlocked||claimed||previewProgress?'disabled':''} onclick="claimReward('${r.id}')">${claimed?'Badge collected':previewProgress?'Sample badge':'Collect badge'}</button></div></article>`}).join('')}</div></section><section class="panel"><h2>Played games</h2>${p.played.length?`<div class="table-wrap"><table><thead><tr><th>Game</th><th>Sport</th><th>Date</th><th>Points</th></tr></thead><tbody>${p.played.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${esc(r.title)}</td><td>${esc(r.sport)}</td><td>${dateLabel(r.date)}</td><td>+100</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No attended games yet. After a completed game, the turf owner can record your attendance in Owner view.</div>'}</section>`;
}
function attendancePanel(){const eligible=state.matches.filter(m=>m.status==='completed'&&m.mine);return `<section class="panel"><h2>Player attendance</h2><p class="muted">Record the demo player’s attendance after a completed, fully committed game. This updates player streaks, records, and rewards.</p>${eligible.length?`<div class="table-wrap"><table><thead><tr><th>Game</th><th>Date</th><th>Attendance</th></tr></thead><tbody>${eligible.map(m=>{const done=(state.attendance||[]).some(r=>r.match===m.id);return `<tr><td>${esc(m.title)}</td><td>${dateLabel(m.date)}</td><td><button class="small" ${done?'disabled':''} onclick="confirmAttendance(${m.id})">${done?'Attendance recorded':'Mark attended'}</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">No completed games with this player awaiting attendance. Bookings alone do not count as play.</div>'}<button style="margin-top:16px" onclick="go('progress')">View player progress ↗</button></section>`}
function confirmAttendance(id){if(role!=='owner'&&role!=='admin')return;const m=state.matches.find(m=>m.id===id);if(!m||!m.mine||m.status!=='completed')return;openModal(`<h2>Record attendance?</h2><p>Confirm that the demo player attended ${esc(m.title)}. This awards 100 play points and updates their weekly streak.</p><div class="actions"><button onclick="closeModal()">Back</button><button class="primary" onclick="recordAttendance(${id})">Confirm attended</button></div>`)}
function recordAttendance(id){const m=state.matches.find(m=>m.id===id);if(!['owner','admin'].includes(role)||!m?.mine||m.status!=='completed'||D.starts(m)+3600000>Date.now())return;state.attendance=P.records(state.attendance);if(state.attendance.some(r=>r.match===id)){closeModal();return}state.attendance.push({match:id,date:m.date,sport:m.sport,title:m.title});save('Attendance recorded. Player earned 100 demo play points.');closeModal();render()}
function claimReward(id){if(previewProgress)return;const p=P.progress(state.attendance||[]),eligible={'first-game':p.played.length>=1,'three-weeks':p.best>=3,'five-games':p.played.length>=5};if(!eligible[id])return;state.claimedRewards=Array.isArray(state.claimedRewards)?state.claimedRewards:[];if(state.claimedRewards.includes(id))return;state.claimedRewards.push(id);save('Achievement badge collected!');render()}
